class Solution:
    def checkZeroOnes(self, s: str) -> bool:
        best = {'0': 0, '1': 0}
        cur, prev = 0, ''
        for ch in s:
            cur = cur + 1 if ch == prev else 1
            best[ch] = max(best[ch], cur)
            prev = ch
        return best['1'] > best['0']

