class Solution {
public:
    bool checkZeroOnes(string s) {
        return longestRun(s, '0') > longestRun(s, '1');
    }
private:
    int longestRun(const string& s, char sep) {
        int best = 0;
        stringstream ss(s);
        string token;
        while (getline(ss, token, sep))
            best = max(best, (int)token.size());
        return best;
    }
};

