class Solution {
    public boolean checkZeroOnes(String s) {
        return longestRun(s, '0') > longestRun(s, '1');
    }

    private int longestRun(String s, char sep) {
        int best = 0;
        for (String seg : s.split(String.valueOf(sep)))
            best = Math.max(best, seg.length());
        return best;
    }
}

